test("trim at consolidation scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "terms-A", "3");
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  await ui.setSetting(pg_uma, "grace-A", "5");
  await ui.setSetting(pg_uma, "proof-threshold-C", "0.50");
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "99.95", "note": ""})).toBe(true);
  await ui.setSetting(pg_uma, "default-grade", "A");
  await ui.setSetting(pg_uma, "clerk-limit-A", "9.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "terms": "20", "contact": " Ada@x "})).toBeNull();
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": " Ada@x ", "tags": "c"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "contact": "ADA@X"})).toBeNull();
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": "20", "termsFrom": "2026-03-12"})).toBe(true);
  const pl_ben_1 = ui.must(await ui.addPlan(pg_uma, p_ben, {"amount": "4.00", "start": "2026-03-09", "end": "2026-04-30", "day": "15"}));
  expect(await ui.pasteClaims(pg_uma, "Ben,10.35,,paste\nBen,10.25,2026-02-10,paste")).toBe(2);
  const c_ben_0 = await ui.claimAt(pg_uma, p_ben, 0);
  const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
  expect(await ui.bulkVoid(pg_uma, [c_ben_0, c_ben_1])).toEqual({ voided: 2, refused: 0 });
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.delegate(pg_wes, {"user": "uma", "from": "2026-03-01", "to": "2026-04-02"})).toBe(true);
  await ui.refresh(pg_uma);
  const c_ben_2 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "4.00", "tags": "b,a,a"}));
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  const c_ben_3 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "99.95", "date": "2026-03-15", "tags": "b,a,a"}));
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
